window.NOTAS=[{"id":"2026-10-22-conagua-revisara-el-agua-de-la-potabilizadora-de-durango-por-su-colora","t":"Conagua revisará el agua de la potabilizadora de Durango por su coloración","c":"durango","f":"2026-10-22T18:59","r":"El agua que sale de la planta potabilizadora y llega a hogares de la capital presenta una coloración fuera de lo normal, por lo que Conagua hará inspecciones y pruebas de laboratorio. Roberto Delgado Gallegos, titular de Conagua en Durango, dijo que podría tratarse de un desajuste en la dosificación de cloro, reactivos, sedimentación o filtración, sin descartar un error humano. La planta la opera la Comisión del Agua del Estado desde agosto de 2025; si la falla está en la red, corresponde a Aguas del Municipio.","b":"","img":"presa","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/revisara-conagua-calidad-del-agua-de-la-planta-potabilizadora-de-durango.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-durango-tuvo-en-agosto-su-desempleo-mas-alto-del-ano-4-1","t":"Durango tuvo en agosto su desempleo más alto del año: 4.1%","c":"economia","f":"2026-10-22T18:58","r":"Según la ENOE del Inegi, la desocupación en Durango llegó a 4.1% en agosto, con 37 mil 105 personas sin empleo, el nivel más alto de 2026. En septiembre bajó a 3.1% (30 mil 770 personas). En los tres meses del tercer trimestre la tasa estatal superó el promedio nacional, que fue de 2.9%, 3.0% y 2.8%.","b":"","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/registra-durango-su-mayor-desempleo-del-2026-durante-el-tercer-trimestre.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-lerdo-fija-condiciones-a-la-planta-de-fertilizantes-de-fermachem","t":"Lerdo fija condiciones a la planta de fertilizantes de Fermachem","c":"laguna","f":"2026-10-22T18:57","r":"La alcaldesa Susy Torrecillas dijo que su gobierno apoyará la planta de urea granulada que Fermachem proyecta en el ejido Sapioriz, declarada proyecto estratégico por el Gobierno de México, con una inversión prevista de 1,600 millones de dólares. La empresa solo podrá usar agua tratada comprada al municipio, unos 150 litros por segundo; no se le permitirá perforar pozos ni obtendrá licencia si vende amoniaco, y deberá construir su propia planta de tratamiento.","b":"","img":"lerdo","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/lerdo-avanza-con-fermachem-y-garantiza-uso-responsable-del-agua-y-desarrollo-sustentable.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-diputados-aprueban-la-llamada-ley-antimemes-con-312-votos","t":"Diputados aprueban la llamada “Ley Antimemes” con 312 votos","c":"politica","f":"2026-10-22T18:56","r":"El pleno de la Cámara de Diputados aprobó la minuta que reforma el Código Penal Federal y la Ley Federal de Protección a la Propiedad Industrial, con 312 votos de Morena, PT y PVEM y 119 en contra de PAN, PRI y MC. Fija hasta cinco años de cárcel a quien use la identidad gráfica de instituciones para engañar y cometer un delito. La oposición protestó con pancartas y advirtió que la redacción puede derivar en censura.","b":"","img":"senado","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/aprueban-ley-antimemes.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-trabajadores-del-imss-en-durango-convocan-a-un-planton-de-12-horas-est","t":"Trabajadores del IMSS en Durango convocan a un plantón de 12 horas este viernes","c":"durango","f":"2026-10-22T18:55","r":"La base trabajadora del IMSS en Durango llamó a un plantón pacífico de 12 horas a partir de las 8:00 del viernes frente a las oficinas de la Sección XVI del sindicato, en la calle Fanny Anitua. Reclaman un aumento salarial insuficiente y falta de respuestas. El comité seccional, encabezado por José Salomón Rodríguez Domínguez, pidió unidad en una circular y se reservó acciones legales.","b":"","img":"imss","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/sindicato-y-trabajadores-del-imss-se-confrontan-convocan-a-nuevo-planton-de-12-horas.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-fiscalia-anticorrupcion-reporta-780-denuncias-en-un-ano-y-casos-en-pue","t":"Fiscalía anticorrupción reporta 780 denuncias en un año y casos en Pueblo Nuevo","c":"politica","f":"2026-10-22T18:54","r":"El fiscal anticorrupción de Durango, Noel Díaz Rodríguez, informó que en mayo se ejecutaron órdenes de aprehensión contra tres exfuncionarios de Pueblo Nuevo —un exdirector jurídico del Ayuntamiento y dos exfuncionarios del Sideapas— y que en julio uno fue sentenciado. En el último año la Fiscalía recibió alrededor de 780 denuncias por corrupción, de las que 150 llegaron a juicio.","b":"","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/fiscalia-anticorrupcion-reporta-acciones-contra-tres-exfuncionarios-de-pueblo-nuevo.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-municipio-de-durango-analiza-cerrar-ocho-bibliotecas-con-poca-asistenc","t":"Municipio de Durango analiza cerrar ocho bibliotecas con poca asistencia","c":"durango","f":"2026-10-22T18:53","r":"El Ayuntamiento administra 21 bibliotecas; tres ya cerraron (Navacoyán, colonia Gobernadores y Ampliación PRI) y se estudia el futuro de otras ocho que reciben de cinco a 10 niños al mes. Giovanni Rosso Güereca, director del Indehval, aclaró que no hay decisión tomada y que la intención es fortalecerlas o buscar otras estrategias. Cada programa cuesta al menos 20 mil pesos mensuales.","b":"","img":"plaza","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/autoridades-analizan-cierre-de-bibliotecas-municipales-en-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-tren-arrastra-un-auto-mas-de-300-metros-en-gomez-palacio-el-conductor","t":"Tren arrastra un auto más de 300 metros en Gómez Palacio; el conductor resulta ileso","c":"laguna","f":"2026-10-22T18:52","r":"Alrededor de las 13:10 de este jueves, una locomotora que circulaba de norte a sur impactó un Chevrolet blanco que salía de la colonia Parque Hundido hacia el bulevar Jabonoso y lo arrastró hasta la parte baja del puente Tlahualilo. El conductor, de 22 años y vecino de Lerdo, dijo que no escuchó el tren; la Cruz Roja lo atendió en el lugar por golpes leves.","b":"","img":"gomez","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/tren-impacta-vehiculo-y-lo-arrastra-mas-de-300-metros-en-gomez-palacio.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-frente-frio-3-deja-madrugadas-de-0-a-5-grados-en-la-sierra-capital-ten","t":"Frente frío 3 deja madrugadas de 0 a 5 grados en la sierra; capital tendrá viernes soleado","c":"durango","f":"2026-10-22T18:51","r":"El SMN prevé mínimas de 0 a 5 °C en la sierra durante la madrugada del viernes y lluvias puntuales fuertes en el norte y occidente del estado, que podrían extenderse al centro el sábado. Para la capital se espera un viernes mayormente soleado, con máxima cercana a 28 °C, mínima de unos 11 °C y probabilidad de lluvia de 2 a 4%. Lerdo podría llegar a 30 °C.","b":"","img":"sierra","foto":"","cred":"","src":[["Contacto Hoy","https://contactohoy.com.mx/local/llega-el-frente-frio-3-y-durango-tendra-mananas-de-hasta-0-grados-en-la-sierra/"],["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/clima-en-durango-viernes-soleado-en-la-capital-y-maxima-cercana-a-los-28-grados.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-romeria-del-panteon-de-oriente-reubican-50-puestos-y-niegan-permiso-a","t":"Romería del Panteón de Oriente: reubican 50 puestos y niegan permiso a tres","c":"durango","f":"2026-10-22T18:50","r":"Las obras del parque lineal Benigno Montoya obligarán a mover al menos 50 de los 800 puestos de la romería de Día de Muertos, informó el regidor Ariel Maa López, quien busca acordar un lugar seguro con los comerciantes inconformes. Además, el director de Inspección Municipal, Ubaldo Salazar Chávez, dijo que tres negocios no tendrán permiso por anomalías en muestreos de alimentos realizados en las fiestas patrias.","b":"","img":"mercado","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/por-obra-de-parque-lineal-reubicaran-50-puestos-de-romeria-del-dia-de-muertos-en-panteon-de-oriente.html"],["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/hallan-anomalias-en-muestreo-de-3-negocios-y-les-niegan-permiso-en-romeria-del-panteon-de-oriente.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-vecinos-de-villas-de-san-francisco-rechazan-obras-de-ecogas","t":"Vecinos de Villas de San Francisco rechazan obras de Ecogas","c":"durango","f":"2026-10-22T18:49","r":"El comité de vecinos del fraccionamiento, con al menos mil habitantes, se opone a que Ecogas abra calles para instalar su red, tras ver maquinaria el miércoles. Dicen que no fueron consultados, que temen por su seguridad y que reúnen firmas; amagaron con bloquear el bulevar Pino Suárez si continúan los trabajos. La nota no incluye postura de la empresa ni de autoridades.","b":"","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/ecogas-es-rechazado-por-vecinos-de-villas-de-san-francisco-en-durango-temen-por-su-seguridad.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-la-cosecha-de-frijol-de-durango-caeria-hasta-60-por-la-sequia","t":"La cosecha de frijol de Durango caería hasta 60% por la sequía","c":"economia","f":"2026-10-22T18:48","r":"El especialista agropecuario Roberto Delgado Gallegos estimó que el ciclo primavera-verano 2026 dejará entre 90 mil y 100 mil toneladas de frijol en Durango, de 50 a 60% menos que el ciclo anterior. Añadió que la cosecha de Estados Unidos también bajará 20%, lo que encarece el grano importado y podría favorecer la venta del frijol duranguense si cumple estándares de calidad.","b":"","img":"sierra","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/preven-menor-cosecha-de-frijol-en-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-trabajo-infantil-en-durango-sube-a-13-7-por-encima-de-la-media-naciona","t":"Trabajo infantil en Durango sube a 13.7%, por encima de la media nacional","c":"durango","f":"2026-10-22T18:47","r":"La Encuesta Nacional de Trabajo Infantil 2025 del Inegi registra en Durango a 60 mil 924 menores de 5 a 17 años en trabajo infantil, 13.7% de ese grupo, frente a 12.6% nacional; en 2022 la tasa estatal era de 13.1%. El 7.5% está en ocupaciones no permitidas por su edad o que dañan su salud y desarrollo, contra 6.6% en el país.","b":"","img":"plaza","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/aumenta-trabajo-infantil-en-durango-supera-la-media-nacional.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-congreso-pide-actas-de-cabildo-detalladas-tras-detectar-irregularidade","t":"Congreso pide actas de Cabildo detalladas tras detectar irregularidades","c":"politica","f":"2026-10-22T18:46","r":"La Comisión de Gobernación del Congreso de Durango aprobó un dictamen, propuesto por el PRI, que obliga a los ayuntamientos a detallar en sus actas lo tratado, el sentido del voto de cada regidor y sus razones. La diputada María del Rocío Rebollo Mendoza explicó que se detectaron casos en que se entregaban listas de asistencia en lugar de actas, y uno en que se reportaron siete votos cuando fueron seis.","b":"","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/detectan-irregularidades-en-actas-de-sesiones-de-cabildo-en-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-durango-podria-recibir-2-100-millones-mas-del-presupuesto-federal-en-2","t":"Durango podría recibir 2,100 millones más del presupuesto federal en 2027","c":"politica","f":"2026-10-22T18:45","r":"El coordinador de regidores de Morena, Luis Iván Gurrola Vega, dijo que, según diputados federales de su partido, el presupuesto para Durango pasaría de 43 mil a 45 mil 100 millones de pesos en 2027. La cifra definitiva se conocerá con la aprobación del Presupuesto de Egresos, prevista para el 15 de noviembre.","b":"","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/presupuesto-para-durango-podria-rebasar-los-45-mil-mdp-en-2027-ivan-gurrola-.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-canacintra-laguna-anticipa-un-2027-complicado-para-la-industria","t":"Canacintra Laguna anticipa un 2027 complicado para la industria","c":"laguna","f":"2026-10-22T18:44","r":"Homero del Bosque, presidente de Canacintra en La Laguna, describió incertidumbre y desánimo entre los industriales por la competencia de China y el alza salarial sin estímulos para las empresas. Reconoció que los cierres no han sido masivos, pero advirtió que algunas compañías se endeudan para cubrir obligaciones como las cuotas del IMSS, y pidió incentivos fiscales a los legisladores.","b":"","img":"torreon","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/empresarios-de-la-laguna-ven-un-panorama-complicado-para-2027.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-inflacion-nacional-sube-a-3-62-en-la-primera-quincena-de-octubre","t":"Inflación nacional sube a 3.62% en la primera quincena de octubre","c":"economia","f":"2026-10-22T18:43","r":"El Inegi reportó una inflación anual de 3.62% en la primera quincena de octubre, con alza quincenal de 0.41%, impulsada por la electricidad (+18.51%) tras el fin del subsidio de verano en 18 ciudades, y por el gas LP. En Durango, la inflación anual de septiembre fue de 3.2%, por debajo del 3.45% nacional.","b":"","img":"bolsa","foto":"","cred":"","src":[["Contacto Hoy","https://contactohoy.com.mx/local/el-bolsillo-de-los-duranguenses-resiente-el-alza-inflacion-llega-a-3-2/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-sheinbaum-anuncia-20-parques-industriales-nuevos-durango-no-esta-en-la","t":"Sheinbaum anuncia 20 parques industriales nuevos; Durango no está en la lista","c":"economia","f":"2026-10-22T18:42","r":"La presidenta presentó 20 parques industriales privados con inversión cercana a 700 millones de dólares y más de 30 mil empleos, en Coahuila, Nuevo León, Baja California, Ciudad de México, Estado de México, Aguascalientes, Guanajuato y Querétaro. Con ellos suman 40 de los 100 previstos en el Plan México. También destacó un crecimiento anual de 3.7% de la actividad económica a septiembre.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/gobierno-de-mexico-anuncia-20-nuevos-parques-industriales-sheinbaum-resalta-avance-economico-de-37/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-rusia-ataca-kiev-y-odesa-horas-despues-de-abrirse-a-negociar","t":"Rusia ataca Kiev y Odesa horas después de abrirse a negociar","c":"internacional","f":"2026-10-22T18:41","r":"El Ministerio de Defensa ruso informó de ataques con misiles y drones durante la noche contra la planta Antonov y otros objetivos en Kiev, y contra el puerto de Kilia, en Odesa. El ataque llegó tras las conversaciones del enviado estadounidense Steve Witkoff con Putin y Zelenski sobre un alto el fuego; Zelenski lo condenó. No se reportaron cifras de víctimas.","b":"","img":"zocalo","foto":"","cred":"","src":[["BioBioChile / EFE","https://www.biobiochile.cl/noticias/internacional/europa/2026/10/22/solo-horas-despues-de-abrirse-a-negociar-la-paz-rusia-lanzo-ataque-con-misiles-contra-ucrania.shtml"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-pablo-hermoso-de-mendoza-y-arturo-gilio-en-la-corrida-villista-del-20","t":"Pablo Hermoso de Mendoza y Arturo Gilio, en la Corrida Villista del 20 de noviembre","c":"entretenimiento","f":"2026-10-22T18:40","r":"La Monumental Plaza de Toros Alejandra de Durango tendrá el Festejo Villista de la Revolución Mexicana el 20 de noviembre a las 20:00, con el rejoneador español Pablo Hermoso de Mendoza y el matador duranguense Arturo Gilio. Los boletos ya están a la venta; los organizadores buscan que el evento se repita cada año.","b":"","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/anuncian-la-corrida-villista-de-la-revolucion-mexicana-en-la-plaza-de-toros-alejandra-en-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-condenan-a-37-anos-de-prision-a-mujer-que-sustrajo-a-una-recien-nacida","t":"Condenan a 37 años de prisión a mujer que sustrajo a una recién nacida del Materno Infantil","c":"durango","f":"2026-10-22T06:40","r":"Karla Daniela Rentería Romero recibió una sentencia de 37 años, 5 meses y 29 días de prisión y una multa de 678,726 pesos por desaparición cometida por particulares, en un procedimiento abreviado, según la Fiscalía General del Estado. La bebé fue sacada del Hospital Materno Infantil de la capital el 23 de octubre de 2025 y localizada al día siguiente en un área verde del fraccionamiento Hacienda Las Flores. Una trabajadora de limpieza del hospital, también vinculada a proceso, espera la resolución de un recurso de revisión.","b":"","img":"gobierno","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/condenan-a-37-anos-de-prision-a-mujer-por-robar-a-una-recien-nacida-en-durango/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-villegas-pide-a-sheinbaum-frenar-la-entrada-de-carne-de-brasil","t":"Villegas pide a Sheinbaum frenar la entrada de carne de Brasil","c":"economia","f":"2026-10-22T06:39","r":"El gobernador Esteban Villegas Villarreal solicitó a la presidenta Claudia Sheinbaum detener el ingreso de carne brasileña, porque, dijo, esa competencia está bajando el precio del ganado mexicano y obliga a los productores a vender más barato. También planteó que la Secretaría de Economía atienda el tema por su efecto en el mercado de la carne.","b":"","img":"ganado","foto":"","cred":"","src":[["Contexto de Durango","https://contextodedurango.com.mx/esteban-villegas-pide-frenar-entrada-de-carne-brasilena-por-impacto-en-ganaderos/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-presidencia-de-lerdo-tercera-autoridad-con-mas-quejas-ante-derechos-hu","t":"Presidencia de Lerdo, tercera autoridad con más quejas ante Derechos Humanos","c":"laguna","f":"2026-10-22T06:38","r":"De enero a septiembre, la Presidencia Municipal de Lerdo acumuló 58 quejas ante la Comisión Estatal de Derechos Humanos de Durango, solo detrás de los agentes del Ministerio Público (74) y la Policía Investigadora (69), según datos publicados por la CEDHD. En total el organismo suma 798 quejas en 2026; la visitaduría de Gómez Palacio, que atiende La Laguna, recibió 112.","b":"","img":"lerdo","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/presidencia-de-lerdo-suma-58-quejas-ante-derechos-humanos-y-ocupa-el-tercer-lugar-en-durango.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-la-corte-penal-internacional-gana-el-premio-sajarov-2026","t":"La Corte Penal Internacional gana el Premio Sájarov 2026","c":"internacional","f":"2026-10-22T06:37","r":"La Conferencia de Presidentes del Parlamento Europeo eligió a la Corte Penal Internacional como ganadora del Premio Sájarov a la libertad de conciencia. El tribunal enfrenta sanciones de Estados Unidos por sus investigaciones relacionadas con Gaza. El galardón se entregará el 16 de diciembre en Estrasburgo.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Tercera","https://www.latercera.com/mundo/noticia/tribunal-penal-internacional-tpi-es-galardonado-con-el-premio-sajarov-2026-del-parlamento-europeo/"],["Libertad Digital","https://www.libertaddigital.com/internacional/europa/2026-10-22/el-tribunal-penal-internacional-recibe-el-premio-sajarov-2026-del-parlamento-europeo-7480285/"]],"dest":true,"a":"Redacción"},{"id":"2026-10-22-first-majestic-atribuye-la-huelga-en-san-dimas-a-un-desacuerdo-por-el","t":"First Majestic atribuye la huelga en San Dimas a un desacuerdo por el ISR de un bono","c":"economia","f":"2026-10-22T06:36","r":"La minera canadiense First Majestic, que opera la mina de San Dimas en Tayoltita, afirmó que el conflicto se debe a que la dirigencia local del sindicato minero se niega a pagar el ISR de un bono discrecional y pide que la empresa lo cubra completo. Sostiene que la mina tiene certificaciones vigentes de la STPS y dijo estar dispuesta a dialogar para alcanzar un acuerdo.","b":"","img":"sierra","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/first-majestic-revela-motivo-del-conflicto-en-mina-de-san-dimas-ratifica-disposicion-al-dialogo.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-produccion-de-oro-en-durango-cae-19-en-agosto-la-plata-sube-6-6","t":"Producción de oro en Durango cae 19% en agosto; la plata sube 6.6%","c":"economia","f":"2026-10-22T06:35","r":"Según el INEGI, Durango produjo 638 kilos de oro en agosto de 2026, 19% menos que los 787 kilos de agosto de 2025. También bajaron el plomo (-5.3%) y el zinc (-2.5%), mientras que la plata creció 6.6%, a 78,537 kilos. A nivel nacional, la producción minerometalúrgica cayó 10.5% anual.","b":"","img":"sierra","foto":"","cred":"","src":[["Contacto Hoy","https://contactohoy.com.mx/local/se-desploma-19-la-produccion-de-oro-en-durango-tambien-cae-el-plomo-y-zinc/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-jueves-soleado-en-durango-con-maxima-de-30-grados","t":"Jueves soleado en Durango, con máxima de 30 grados","c":"durango","f":"2026-10-22T06:34","r":"Conagua prevé cielo soleado en la capital este jueves, con máxima de 30 °C, rachas de viento de hasta 20 km/h y sin lluvia; solo se esperan lluvias ligeras en la sierra. El miércoles, la mínima más baja del estado fue de 1 °C en La Rosilla, Guanaceví, y Tamazula llegó a 39 °C.","b":"","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/pese-a-dias-soleados-siguen-las-bajas-temperaturas-en-durango-asi-sera-el-clima-el-22-de-octubre.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-rehabilitacion-del-parque-forestal-de-lerdo-terminara-en-enero-de-2027","t":"Rehabilitación del Parque Forestal de Lerdo terminará en enero de 2027","c":"laguna","f":"2026-10-22T06:33","r":"La Secope asignó un contrato de 19.8 millones de pesos, sin IVA, para renovar el Parque Forestal Lerdo, antes Las Auras; la inversión total supera los 26 millones e incluye una línea de agua tratada para regar unos 4 mil árboles en 11 hectáreas. El plazo vence el 21 de enero de 2027. El gobernador dijo que habrá más árboles e iluminación, mientras un colectivo pide estudios ambientales.","b":"","img":"bosque","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/rehabilitacion-del-parque-forestal-en-lerdo-avanza-con-inversion-superior-a-26-millones-de-pesos.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-federacion-invertira-hasta-13-mil-millones-en-obras-de-agua-para-jalis","t":"Federación invertirá hasta 13 mil millones en obras de agua para Jalisco","c":"nacional","f":"2026-10-22T06:32","r":"La presidenta Claudia Sheinbaum anunció que el Gobierno federal aportará entre 12 mil y 13 mil millones de pesos para obras hidráulicas que atiendan la crisis de agua en la zona metropolitana de Guadalajara, con cifras de Conagua. Dijo que se buscará financiarlas sin deuda.","b":"","img":"presa","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/noticia/2026/10/21/estados/sheinbaum-anuncia-inversion-de-13-mil-mdp-en-una-planta-potabilizadora-en-jalisco"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-el-ebola-llega-a-nigeria-y-kenia-suma-nueve-casos","t":"El ébola llega a Nigeria y Kenia suma nueve casos","c":"internacional","f":"2026-10-22T06:31","r":"Nigeria confirmó su primer caso de ébola en Abuja, un paciente que llegó desde Uganda; se da seguimiento a 44 contactos. Kenia suma nueve casos y una muerte, con 134 personas en cuarentena. El brote en la República Democrática del Congo, iniciado en mayo, deja al menos 4 mil muertes.","b":"","img":"zocalo","foto":"","cred":"","src":[["Diario de Yucatán","https://www.yucatan.com.mx/mundo/2026/10/20/brote-de-ebola-nigeria-registra-su-primer-caso-y-kenia-el-noveno.html"],["Al Jazeera","https://www.aljazeera.com/news/2026/10/20/kenya-confirms-ninth-ebola-case"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-juicios-de-divorcio-en-durango-suben-8-8-en-2026","t":"Juicios de divorcio en Durango suben 8.8% en 2026","c":"durango","f":"2026-10-22T06:30","r":"De enero a septiembre se abrieron 4,855 juicios de divorcio en el estado, 392 más que en el mismo periodo de 2025, según el Poder Judicial. El 88% fueron divorcios incausados. El distrito de Durango concentró 2,137 casos, Gómez Palacio 1,429 y Lerdo 557.","b":"","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/han-aumentado-los-divorcios-en-durango-esto-dice-el-poder-judicial-del-estado.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-hoteles-y-restaurantes-de-durango-ganan-ingresos-pero-pierden-3-4-de-p","t":"Hoteles y restaurantes de Durango ganan ingresos pero pierden 3.4% de personal","c":"economia","f":"2026-10-22T06:29","r":"En agosto, los ingresos reales del sector de alojamiento y preparación de alimentos en Durango subieron 16.3% anual, pero su personal ocupado bajó 3.4%, según la Encuesta Mensual de Servicios del INEGI. Los servicios de medios masivos crecieron 25.6% en ingresos.","b":"","img":"plaza","foto":"","cred":"","src":[["Contacto Hoy","https://contactohoy.com.mx/local/cae-3-4-el-personal-ocupado-en-hoteles-y-restaurantes-de-durango-segun-datos-del-inegi/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-hay-164-vacantes-formales-en-durango-y-la-laguna-hasta-el-23-de-octubr","t":"Hay 164 vacantes formales en Durango y La Laguna hasta el 23 de octubre","c":"economia","f":"2026-10-22T06:28","r":"El Gobierno estatal informó de 164 vacantes de 109 empresas, 94 en la capital y 70 en la Región Laguna, con sueldos desde el mínimo hasta 28 mil pesos. Están vigentes hasta el 23 de octubre y se consultan en empleo.gob.mx o en las oficinas del Servicio Nacional de Empleo en Durango y Gómez Palacio.","b":"","img":"gobierno","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/estados/esteban-villegas-anuncia-164-vacantes-de-empleo-con-sueldos-de-hasta-28-mil-pesos-en-durango/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-cierres-viales-en-lerdo-el-viernes-por-la-carrera-marea-rosa","t":"Cierres viales en Lerdo el viernes por la carrera Marea Rosa","c":"laguna","f":"2026-10-22T06:27","r":"La carrera Marea Rosa Music Fest 2026 se correrá el viernes 23 de octubre a las 18:30 horas, con el Parque Victoria como punto central. Los cierres empiezan a las 14:00 en avenidas como Francisco Sarabia, Coronado, Zaragoza y Matamoros, varias calles del centro y un tramo del bulevar Miguel Alemán.","b":"","img":"lerdo","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/lerdo-anuncia-cierre-de-vialidades-por-carrera-marea-rosa-music-fest-2026.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-tormenta-tropical-vance-se-mantiene-lejos-de-las-costas-de-mexico","t":"Tormenta tropical Vance se mantiene lejos de las costas de México","c":"nacional","f":"2026-10-22T06:26","r":"La tormenta tropical Vance se ubica en el Pacífico a más de 700 kilómetros al sur de Guerrero y por ahora no tiene efectos en el país. Mientras, el frente frío 3 entra por el noroeste con lluvias y rachas de 40 a 60 km/h en Sonora y Chihuahua.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/22/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-jueves-22-de-octubre-frente-frio-provocara-lluvias-mientras-vance-se-estaciona-en-el-pacifico/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-unipoli-entrega-178-titulos-de-tecnico","t":"Unipoli entrega 178 títulos de técnico; casi toda la generación irá por la ingeniería","c":"educacion","f":"2026-10-22T06:25","r":"La Universidad Politécnica de Durango graduó a 178 Técnicos Superiores Universitarios de la generación 2024-2026, con promedio general de 8.9. Según el rector Arturo Fragoso Corral, casi todos continuarán unos 16 meses más para obtener el título de ingeniería o licenciatura. Construcción fue el programa con más egresados (56).","b":"","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/se-graduan-178-tecnicos-de-la-unipoli-casi-todos-seguiran-estudiando.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-diputada-pide-garantizar-mastografias-en-todo-el-estado","t":"Diputada pide garantizar mastografías en todo el estado","c":"politica","f":"2026-10-22T06:24","r":"La diputada local Flora Leal Méndez pidió que las mujeres de la capital y de localidades alejadas tengan acceso a mastografías, diagnóstico y tratamiento sin importar su derechohabiencia. Citó que en 2024 Durango tuvo 17.5 muertes por cáncer de mama por cada 100 mil mujeres de 20 años y más, según el INEGI.","b":"","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/piden-garantizar-la-deteccion-oportuna-de-cancer-de-mama-en-todo-el-estado-de-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-consultorio-movil-de-salud-orienta-a-jovenes-sobre-anticonceptivos","t":"Consultorio móvil de Salud orienta a jóvenes sobre anticonceptivos","c":"durango","f":"2026-10-22T06:23","r":"La Secretaría de Salud de Durango lleva a escuelas, colonias y poblados un consultorio móvil de educación sexual dirigido sobre todo a personas de 10 a 19 años, donde explican métodos anticonceptivos y canalizan a centros de salud. La responsable del programa, Rubí Miranda Vázquez, recomendó no informarse solo en redes sociales.","b":"","img":"imss","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/acercan-metodos-anticonceptivos-a-adolescentes-y-jovenes-en-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-brewers-y-rays-abren-la-serie-mundial-el-viernes-en-milwaukee","t":"Brewers y Rays abren la Serie Mundial el viernes en Milwaukee","c":"deportes","f":"2026-10-22T06:22","r":"Milwaukee, con el mejor récord de las Grandes Ligas (103-59), recibe a Tampa Bay en el primer juego el viernes 23 de octubre en el American Family Field. Los Brewers barrieron a los Dodgers en la Serie de Campeonato y los Rays vencieron a Cleveland en seis juegos. Ninguno de los dos ha ganado un título.","b":"","img":"beisbol","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/colombia/2026/10/22/serie-mundial-2026-hora-y-donde-ver-en-colombia-el-juego-1-de-la-final-entre-milwaukee-brewers-y-tampa-bay-rays/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-22-orionidas-la-lluvia-de-estrellas-alcanza-su-maximo-esta-madrugada","t":"Oriónidas: la lluvia de estrellas alcanza su máximo esta madrugada","c":"durango","f":"2026-10-22T06:21","r":"Las Oriónidas tienen su pico la noche del miércoles 21 a la madrugada del jueves 22, con 10 a 20 meteoros por hora en cielos oscuros, aunque la Luna restará visibilidad. Se recomienda observar después de la medianoche y antes del amanecer, lejos de la luz urbana; la lluvia sigue activa hasta el 7 de noviembre.","b":"","img":"sierra","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/orionidas-2026-en-durango-cuando-y-como-ver-la-lluvia-de-estrellas-esta-semana.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-huelga-en-la-mina-de-san-dimas-deja-a-mas-de-400-trabajadores-sin-empl","t":"Huelga en la mina de San Dimas deja a más de 400 trabajadores sin empleo","c":"economia","f":"2026-10-21T18:59","r":"Más de 400 empleados de empresas contratistas de la mina de San Dimas, en Tayoltita, fueron liquidados por el conflicto laboral que mantiene detenida la operación desde el 18 de septiembre y que se convirtió en huelga el 8 de octubre. Contratistas locales señalan que el paro ya golpea la economía de la comunidad.","b":"First Majestic, empresa que opera la mina, atribuye el conflicto a que la dirigencia local del sindicato minero se niega a pagar el ISR de un bono discrecional y pide que la compañía cubra el monto completo. La empresa asegura que las quejas de seguridad no formaban parte de las demandas originales, que la mina tiene certificaciones vigentes de la Secretaría del Trabajo y que mantiene abierto el diálogo para lograr un acuerdo que permita el regreso de los trabajadores.","img":"sierra","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/huelga-en-mina-deja-400-despidos.html"],["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/first-majestic-revela-motivo-del-conflicto-en-mina-de-san-dimas-ratifica-disposicion-al-dialogo.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-21-villegas-pide-hospitales-nuevos-del-issste-en-durango-y-gomez-palacio","t":"Villegas pide hospitales nuevos del ISSSTE en Durango y Gómez Palacio","c":"durango","f":"2026-10-21T18:58","r":"El gobernador Esteban Villegas calificó como no funcionales los hospitales del ISSSTE en la capital y en Gómez Palacio, cuyos quirófanos están fuera de servicio por daños estructurales; dijo que ya no conviene invertir en ellos y que deben construirse nuevos. Mientras tanto, la Secretaría de Salud estatal cubre las cirugías.","b":"Villegas dijo que el hospital de Gómez Palacio sería reubicado o rescatado este año o a inicios del próximo, mientras que el de la capital sigue pendiente. También respaldó a los trabajadores del IMSS que protestan por el aumento salarial y la falta de insumos y medicamentos, que atribuyó a fallas federales en la compra consolidada. Sobre una posible renuncia del director del IMSS, Zoé Robledo, dijo que esa decisión corresponde a la presidenta Claudia Sheinbaum.","img":"gobierno","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/esteban-villegas-califica-de-infuncionales-hospitales-del-issste-en-durango-y-gomez-palacio.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-21-hasta-40-de-las-empresas-de-durango-pedira-prestamos-para-pagar-aguina","t":"Hasta 40% de las empresas de Durango pedirá préstamos para pagar aguinaldos","c":"economia","f":"2026-10-21T18:57","r":"Entre 35% y 40% de las empresas duranguenses podría recurrir a créditos para cubrir aguinaldos y prestaciones de fin de año, estimó Joana Soto Quintero, presidenta de Canacintra Durango. Explicó que la mayoría ha mantenido su plantilla, pero que 2026 tuvo meses de repunte y otros muy complicados.","b":"","img":"mercado","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/hasta-40-de-las-empresas-de-durango-recurrira-a-creditos-para-pagar-aguinaldos.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-21-seis-empresas-compiten-por-sustituir-el-emisor-central-de-drenaje-de-g","t":"Seis empresas compiten por sustituir el emisor central de drenaje de Gómez Palacio","c":"laguna","f":"2026-10-21T18:56","r":"Seis constructoras se interesaron en la licitación de la primera etapa del nuevo emisor central de drenaje de Gómez Palacio, con inversión de 200 millones de pesos aportados por el municipio y el estado. Las propuestas se abrirán el 26 de octubre y el fallo se dará el 30.","b":"El proyecto completo cuesta 570 millones de pesos e incluye la rehabilitación del colector San Ignacio; la segunda etapa, de 370 millones, la licitará y pagará el gobierno federal. La primera etapa se ejecutaría del 9 de noviembre de 2026 al 7 de mayo de 2027. Según la Comisión del Agua del Estado de Durango, la obra forma parte del Plan Fluye y beneficiará a más de 301 mil habitantes.","img":"gomez","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/seis-empresas-buscan-contrato-para-sustituir-emisor-central-de-drenaje-en-gomez-palacio.html"]],"dest":true,"a":"Redacción"},{"id":"2026-10-21-comienzan-los-pagos-de-la-beca-benito-juarez-en-durango","t":"Comienzan los pagos de la Beca Benito Juárez en Durango","c":"educacion","f":"2026-10-21T18:55","r":"La coordinación estatal de las Becas Benito Juárez informó que ya se depositan los pagos a unos 50 mil estudiantes de bachillerato y 6 mil de universidad que continúan en el programa. Los cerca de 30 mil nuevos alumnos de media superior recibirán su tarjeta en noviembre y diciembre, con un solo depósito por dos bimestres.","b":"Jazmín Areli Nevárez Sarmiento, coordinadora estatal, señaló que el registro a la beca Rita Cetina para primaria y secundaria estará abierto en línea del 26 de octubre al 6 de noviembre. El 23 de octubre habrá una asamblea virtual para quienes no puedan acudir en persona.","img":"plaza","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/inician-pagos-de-beca-benito-juarez-en-durango-anuncian-entrega-de-tarjetas-a-nuevos-beneficiarios.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-regidor-cuestiona-la-centralizacion-del-catastro-y-pide-no-subir-el-pr","t":"Regidor cuestiona la centralización del catastro y pide no subir el predial en 2027","c":"politica","f":"2026-10-21T18:54","r":"El regidor Ignacio Orrante Ramírez advirtió en el Cabildo de Durango que la nueva ley general de armonización catastral podría reducir facultades municipales y encarecer el predial al actualizar los valores de los predios. Dijo que votará contra cualquier aumento del impuesto en 2027.","b":"Orrante recordó que el municipio recauda unos 700 millones de pesos al año con ingresos propios, mientras su nómina ronda los 1,200 millones. Las autoridades federales sostienen que la ley no crea impuestos ni sube por sí misma las tasas del predial.","img":"catedral2","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/cuestionan-en-cabildo-de-durango-la-centralizacion-del-catastro.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-cuatro-presas-de-durango-llegan-o-rebasan-el-100-de-su-capacidad","t":"Cuatro presas de Durango llegan o rebasan el 100% de su capacidad","c":"durango","f":"2026-10-21T18:53","r":"Las 10 principales presas del estado recibieron 249 millones de metros cúbicos de agua en lo que va de octubre, y cuatro ya alcanzaron o superaron su nivel máximo. El Distrito de Riego 052 promedia 96.2% de almacenamiento.","b":"En el norte, la presa San Gabriel, en Ocampo, subió de 24% a 33.1%, y la Lázaro Cárdenas, en Indé, de 27% a 36.8%; la de Villa Hidalgo se mantiene en 36.4%.","img":"presa","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/rebasan-4-presas-su-nivel-maximo.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-violencia-familiar-el-delito-mas-llevado-a-juicio-en-durango-en-2026","t":"Violencia familiar, el delito más llevado a juicio en Durango en 2026","c":"durango","f":"2026-10-21T18:52","r":"De enero a septiembre se abrieron 5,190 causas penales en juzgados de primera instancia del estado; 1,141 fueron por violencia familiar, seguidas de lesiones (905) y robo (516), según la Dirección de Estadística del Poder Judicial de Durango.","b":"En el mismo periodo se registraron 482 causas por delitos contra la salud, 423 por daños, 344 por fraude, 95 por homicidio y 17 por feminicidio.","img":"catedral","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/violencia-familiar-encabeza-causas-penales-en-durango-de-enero-a-septiembre-de-2026.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-guanacevi-registra-1-c-la-capital-tendra-un-miercoles-soleado","t":"Guanaceví registra 1 °C; la capital tendrá un miércoles soleado","c":"durango","f":"2026-10-21T18:51","r":"La Rosilla, en Guanaceví, amaneció el martes con 1 °C, la temperatura más baja del estado. Para este miércoles, Conagua prevé en la ciudad de Durango un día mayormente soleado, sin lluvia, con mínima de 13 °C y máxima de 28 °C.","b":"Podría haber lluvias ligeras en la sierra y el norte del estado, y rachas de viento de hasta 30 kilómetros por hora en la capital.","img":"sierra","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/durango-registra-temperatura-de-1-grado-como-sera-el-clima-este-21-de-octubre.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-canaco-durango-advierte-que-la-jornada-laboral-mas-corta-subira-costos","t":"Canaco Durango advierte que la jornada laboral más corta subirá costos","c":"economia","f":"2026-10-21T18:50","r":"El presidente de Canaco Durango, Sergio Sánchez López, dijo que la reducción de la jornada laboral tendrá un impacto inevitable en los costos de operación y que algunas empresas podrían recortar personal. Propuso acordar horarios con los trabajadores para que el cambio sea sostenible.","b":"","img":"mercado","foto":"","cred":"","src":[["El Siglo de Durango","https://www.elsiglodedurango.com.mx/noticia/2026/reduccion-de-jornada-laboral-elevara-costos-de-operacion-advierte-canaco-durango.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-lerdo-tendra-un-periferico-interno-sobre-el-canal-que-rodea-la-ciudad","t":"Lerdo tendrá un periférico interno sobre el canal que rodea la ciudad","c":"laguna","f":"2026-10-21T18:49","r":"El gobernador Esteban Villegas anunció un periférico interno en Lerdo que se construiría cubriendo el canal que rodea la ciudad; la primera etapa sería de 4 kilómetros. La obra arrancaría a finales de 2026 o inicios de 2027, una vez que se acuerde con Conagua.","b":"Villegas dijo que el estado ya tiene los recursos, aunque no precisó el monto, y que el paquete económico 2027 se enviará al Congreso local a finales de noviembre.","img":"lerdo","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/anuncian-construccion-de-periferico-interno-en-municipio-de-lerdo.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-entregan-el-parque-victoria-de-lerdo-rehabilitado-y-una-cancha-nueva","t":"Entregan el Parque Victoria de Lerdo rehabilitado y una cancha nueva","c":"laguna","f":"2026-10-21T18:48","r":"El gobernador Esteban Villegas y la alcaldesa Susy Torrecillas entregaron la rehabilitación del Parque Victoria y una cancha de futbol rápido en Lerdo, con una inversión conjunta de casi 7 millones de pesos.","b":"El parque, en la calle Chihuahua entre Madero y Coronado, costó 5.46 millones e incluye alumbrado, juegos infantiles y área de ejercicio; la cancha, que esperaba arreglo desde hacía cinco años, costó 1.5 millones.","img":"lerdo","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/rehabilitan-parque-victoria-y-cancha-en-lerdo-por-casi-7-millones-de-pesos.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-gomez-palacio-vacuna-gratis-en-la-presidencia-municipal-hasta-el-23-de","t":"Gómez Palacio vacuna gratis en la Presidencia Municipal hasta el 23 de octubre","c":"laguna","f":"2026-10-21T18:47","r":"La Dirección de Salud de Gómez Palacio instaló en el vestíbulo de la Presidencia un módulo de la campaña invernal de vacunación, que opera del 19 al 23 de octubre. Aplica gratis vacunas contra influenza, COVID-19 y neumococo, además de tétanos, sarampión, hepatitis y VPH.","b":"Se recomienda llevar la cartilla de vacunación. No deben vacunarse personas con alergia a algún componente o con fiebre.","img":"gomez","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/gomez-palacio-arranca-campana-invernal-de-vacunacion-en-la-presidencia-municipal.html"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-imss-ofrece-aumento-de-8-y-el-sindicato-lo-acepta","t":"IMSS ofrece aumento de 8% y el sindicato lo acepta","c":"politica","f":"2026-10-21T18:46","r":"El director del IMSS, Zoé Robledo, subió su propuesta de 6.8% a un incremento global de 8%: 4% al salario tabular y 4% como ayuda para renta de vivienda, según Milenio; el Sindicato Nacional de Trabajadores del Seguro Social (SNTSS) lo aceptó. En la mañanera, Claudia Sheinbaum dijo que es posible recortar gastos del instituto para dar un aumento mayor y que Robledo presentará una propuesta integral de salarios e insumos.","b":"","img":"imss","foto":"","cred":"","src":[["Milenio","https://www.milenio.com/politica/pulso-politico-ultimas-noticias-politica-mexico-hoy-21-octubre"],["Infobae","https://www.infobae.com/mexico/2026/10/21/la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-miercoles-21-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-el-dolar-cierra-en-18-67-pesos-el-peso-pierde-mas-de-1","t":"El dólar cierra en 18.67 pesos; el peso pierde más de 1%","c":"economia","f":"2026-10-21T18:45","r":"El tipo de cambio cerró este miércoles en 18.67 pesos por dólar, frente a 18.43 del cierre previo, con base en datos de Dow Jones citados por Infobae. En la semana, el dólar acumula un avance de 0.96%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/21/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-21-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-zona-de-baja-presion-frente-a-oaxaca-podria-volverse-ciclon-tropical","t":"Zona de baja presión frente a Oaxaca podría volverse ciclón tropical","c":"nacional","f":"2026-10-21T18:44","r":"Una zona de baja presión a unos 720 kilómetros al suroeste de Oaxaca tiene 90% de probabilidad de convertirse en ciclón tropical en las próximas 48 horas, según el SMN. Se pronostican lluvias intensas en Veracruz y Oaxaca, muy fuertes en Puebla, Tabasco, Chiapas, Quintana Roo y Guerrero, y rachas de hasta 70 km/h en el Golfo de Tehuantepec.","b":"","img":"huracan","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/21/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-miercoles-21-de-octubre-formacion-de-nuevo-frente-frio-activa-alerta-por-lluvias-y-bajas-temperaturas/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-pemex-preve-invertir-mas-de-1-8-billones-de-pesos-con-recursos-propios","t":"Pemex prevé invertir más de 1.8 billones de pesos con recursos propios","c":"economia","f":"2026-10-21T18:43","r":"El director de Pemex, Juan Carlos Carpio, informó en la mañanera una inversión superior a 1.8 billones de pesos para los próximos años, financiada solo con recursos de la empresa, para sostener la producción, la refinación, la petroquímica y los fertilizantes. Sheinbaum dijo que la producción de gasolinas compensa la baja en las exportaciones.","b":"","img":"pemex","foto":"","cred":"","src":[["Milenio","https://www.milenio.com/politica/pulso-politico-ultimas-noticias-politica-mexico-hoy-21-octubre"],["Infobae","https://www.infobae.com/mexico/2026/10/21/la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-miercoles-21-de-octubre/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-lula-y-flavio-bolsonaro-cierran-campana-rumbo-a-la-segunda-vuelta-en-b","t":"Lula y Flávio Bolsonaro cierran campaña rumbo a la segunda vuelta en Brasil","c":"internacional","f":"2026-10-21T18:42","r":"Brasil elegirá presidente el 25 de octubre en una segunda vuelta entre Luiz Inácio Lula da Silva y Flávio Bolsonaro. Este miércoles Lula hizo campaña en Belo Horizonte y Bolsonaro en São Luís, de acuerdo con la agenda de EFE.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/10/21/temas-del-dia-de-efe-internacional-del-miercoles-21-de-octubre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-witkoff-viaja-a-san-petersburgo-para-impulsar-la-paz-en-ucrania","t":"Witkoff viaja a San Petersburgo para impulsar la paz en Ucrania","c":"internacional","f":"2026-10-21T18:41","r":"El enviado estadounidense Steve Witkoff visitó San Petersburgo para impulsar que Rusia retome las negociaciones de paz sobre Ucrania con mediación de EE.UU., informó EFE. Putin ofreció mediar en la guerra de Irán. Rusia dijo haber derribado 373 drones ucranianos de largo alcance durante la noche.","b":"","img":"zocalo","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/10/21/temas-del-dia-de-efe-internacional-del-miercoles-21-de-octubre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-otro-superpetrolero-se-incendia-tras-chocar-con-una-mina-en-ormuz","t":"Otro superpetrolero se incendia tras chocar con una mina en Ormuz","c":"internacional","f":"2026-10-21T18:40","r":"Irán reportó que otro superpetrolero se incendió tras chocar con una mina en el estrecho de Ormuz. El canciller Abbas Araghchi aseguró que las conversaciones con Estados Unidos continúan con mediación de Pakistán, según EFE.","b":"","img":"pemex","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/10/21/temas-del-dia-de-efe-internacional-del-miercoles-21-de-octubre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-10-21-mexico-tiene-cuatro-oportunidades-mas-para-ganar-plazas-a-los-angeles","t":"México tiene cuatro oportunidades más para ganar plazas a Los Ángeles 2028","c":"deportes","f":"2026-10-21T18:39","r":"México aún puede sumar plazas olímpicas para Los Ángeles 2028 en noviembre y diciembre: el Mundial de tiro en Doha, el Campeonato NORCECA de voleibol de playa en Puerto Rico, los Juegos Mundiales de surf ISA en Perú y el Campeonato Femenil de la Concacaf. Ya están clasificados el flag football femenil y el futbol varonil.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/10/21/estos-son-los-eventos-en-los-que-mexico-aun-puede-buscar-el-boleto-olimpico-en-2026/"]],"dest":false,"a":"Redacción"}];
window.HOY={"fecha":"Jueves 22 de octubre de 2026","actualizado":"18:40 h","clima":{"ahora":"","max":28,"min":11,"texto":"Pronóstico para el viernes: jornada mayormente soleada en la capital, con algunas nubes al final de la tarde y viento ligero. El frente frío 3 deja madrugadas de 0 a 5 °C en la sierra y lluvias puntuales fuertes en el norte y occidente del estado.","laguna_max":30,"laguna_min":"","filas":[{"nombre":"Probabilidad de lluvia (capital)","valor":"2 a 4%","nivel":"ok"},{"nombre":"Viento (capital)","valor":"Ligero","nivel":"ok"},{"nombre":"Mínimas en la sierra (viernes)","valor":"0 a 5 °C","nivel":"warn"},{"nombre":"Lluvias fuertes puntuales","valor":"Norte y occidente del estado","nivel":"warn"}]},"carreteras":[],"indicadores":[{"nombre":"Dólar","valor":"$18.71","nota":"Cierre del jueves (Dow Jones)"},{"nombre":"Gasolina Magna","valor":"$23.90","nota":"Promedio en la capital"},{"nombre":"Gasolina Premium","valor":"$29.09","nota":"Promedio en la capital"},{"nombre":"Diésel","valor":"$26.96","nota":"Promedio en la capital"}],"agenda":[{"hora":"23 oct, 8:00","texto":"Plantón de 12 horas de trabajadores del IMSS frente a la Sección XVI del sindicato, calle Fanny Anitua"},{"hora":"Hasta 23 oct","texto":"Vacunación invernal gratuita en la Presidencia Municipal de Gómez Palacio"},{"hora":"23 oct","texto":"Asamblea virtual de las Becas Benito Juárez para nuevos beneficiarios"},{"hora":"23 oct, 18:30","texto":"Carrera Marea Rosa Music Fest en Lerdo; cierres viales desde las 14:00 alrededor del Parque Victoria"},{"hora":"26 oct","texto":"Abre el registro en línea a la beca Rita Cetina (primaria y secundaria)"},{"hora":"20 nov, 20:00","texto":"Festejo Villista de la Revolución en la Plaza de Toros Alejandra; boletos a la venta"}]};
